{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Plans — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Cohort-based wellness offerings for steady daily practice. Outcomes, habits, and frameworks you can use." />
  <style>
    :root{--bg:#fbfbfc;--card:#ffffff;--accent:#6b5ce8;--muted:#6b7280;--glass:rgba(107,92,232,0.08)}
    *{box-sizing:border-box}
    body{font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;line-height:1.4;color:#0f172a;background:var(--bg);margin:0}
    header{background:linear-gradient(180deg,rgba(107,92,232,0.06),transparent);backdrop-filter:blur(6px);position:sticky;top:0;z-index:30}
    .wrap{max-width:1100px;margin:0 auto;padding:24px}
    nav{display:flex;align-items:center;justify-content:space-between;gap:16px}
    .brand{display:flex;align-items:center;gap:12px;font-weight:700;color:#0f172a}
    .nav-links{display:flex;gap:14px}
    .nav-links a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:8px}
    .nav-links a[href$="pricing.html"]{color:var(--accent);font-weight:600}
    .hero{padding:56px 24px 36px;background:url('assets/img/pattern.svg') center/600px repeat;border-bottom:1px solid rgba(15,23,42,0.04)}
    .hero h1{margin:0;font-size:28px;color:#0f172a}
    .hero p{margin:12px 0 0;color:var(--muted)}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:20px;margin-top:28px}

    /* cards */
    .card{background:var(--card);border-radius:12px;padding:18px;box-shadow:0 6px 18px rgba(15,23,42,0.04)}
    .plan{border:1px solid rgba(15,23,42,0.04)}
    .plan h3{margin:0 0 8px}
    .price{font-size:22px;color:var(--accent);font-weight:700}
    .small{color:var(--muted);font-size:13px}

    /* table */
    .plans-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
    .feature{display:flex;align-items:flex-start;gap:10px;margin:10px 0}

    /* CTA */
    .cta{display:inline-block;background:var(--accent);color:#fff;padding:10px 14px;border-radius:10px;text-decoration:none}

    /* reveal animation */
    .reveal-hidden{opacity:0;transform:translateY(18px);transition:opacity .5s ease,transform .6s cubic-bezier(.2,.9,.3,1)}
    @media (prefers-reduced-motion: reduce){.reveal-hidden{opacity:1;transform:none;transition:none}}

    /* modal */
    .overlay{position:fixed;inset:0;background:rgba(2,6,23,0.48);display:none;align-items:center;justify-content:center;padding:20px;z-index:60}
    .overlay.open{display:flex}
    .modal{background:var(--card);border-radius:12px;padding:18px;max-width:720px;width:100%;box-shadow:0 10px 40px rgba(15,23,42,0.2)}
    .modal h2{margin:0 0 8px}
    .modal .steps{display:flex;gap:8px;margin:10px 0 14px}
    .step{flex:1;padding:10px;border-radius:8px;background:var(--glass);text-align:center;font-size:13px}
    .modal .body{min-height:120px}
    .controls{display:flex;gap:8px;justify-content:flex-end;margin-top:12px}
    button{cursor:pointer}
    .btn-ghost{background:transparent;border:1px solid rgba(15,23,42,0.06);padding:8px 12px;border-radius:8px}
    .btn-primary{background:var(--accent);color:#fff;padding:8px 12px;border-radius:8px;border:none}

    footer{padding:28px 24px;color:var(--muted);border-top:1px solid rgba(15,23,42,0.04);margin-top:40px}

    @media (max-width:880px){.grid{grid-template-columns:1fr}.plans-grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div class="wrap">
      <nav>
        <div class="brand">
          <svg width="36" height="36" viewBox="0 0 36 36" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden>
            <rect width="36" height="36" rx="8" fill="url(#g)" />
            <path d="M10 20c3 2 6 2 9 0" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" />
            <defs><linearGradient id="g" x1="0" x2="1"><stop offset="0" stop-color="#8b79f5"/><stop offset="1" stop-color="#6b5ce8"/></linearGradient></defs>
          </svg>
          <span>{{BUSINESS_NAME}}</span>
        </div>
        <div class="nav-links">
          <a href="index.html">Home</a>
          <a href="programs.html">Journeys</a>
          <a href="services.html">Sessions</a>
          <a href="testimonials.html">Stories</a>
          <a href="pricing.html">Pricing</a>
          <a href="book.html">Reserve</a>
        </div>
      </nav>
    </div>
  </header>

  <main>
    <section class="hero wrap reveal-hidden">
      <h1>Choose your next steady habit system</h1>
      <p>Small cohorts. Clear frameworks. Practice-focused outcomes that shape how your week unfolds — not just another to-do.</p>
      <div style="margin-top:14px;display:flex;gap:10px;align-items:center">
        <a class="cta" href="#cohorts">Explore cohorts</a>
        <button class="btn-ghost" id="try-btn">Try it now</button>
      </div>
    </section>

    <section class="wrap grid">
      <div>
        <div id="cohorts" class="card plan reveal-hidden">
          <h3>Bridge Cohort — 6 weeks</h3>
          <div class="price">$299 per participant</div>
          <div class="small">Live group rhythm, weekly frameworks, habit maps.</div>
          <div style="margin-top:12px">
            <div class="feature"><div style="width:10px;height:10px;background:var(--accent);border-radius:4px;margin-top:6px"></div>
              <div><strong>Outcomes:</strong> 2 daily anchor habits + weekly review ritual</div></div>
            <div class="feature"><div style="width:10px;height:10px;background:#10b981;border-radius:4px;margin-top:6px"></div>
              <div><strong>Includes:</strong> workbook, 3 live sessions, private cohort channel</div></div>
          </div>
        </div>

        <div class="plans-grid" style="margin-top:14px">
          <div class="card reveal-hidden">
            <h3>Launch Cohort — 3 weeks</h3>
            <div class="price">$149</div>
            <div class="small">Rapid habit seeding with twice-weekly check-ins.</div>
          </div>
          <div class="card reveal-hidden">
            <h3>Anchor Cohort — 12 weeks</h3>
            <div class="price">$499</div>
            <div class="small">Long-form integration and steady habit calibration.</div>
          </div>
          <div class="card reveal-hidden">
            <h3>Micro Cohorts</h3>
            <div class="price">Sliding scale</div>
            <div class="small">Pay what fits for community access and accountability.</div>
          </div>
        </div>

      </div>

      <aside class="card reveal-hidden">
        <h4>Why cohort pricing?</h4>
        <p class="small">Cohorts focus on shared practice rhythms. Pricing is framed per participant and intentionally simple: enough structure to move habits, with space to land them into life.</p>
        <div style="margin-top:12px">
          <strong>What's included</strong>
          <ul class="small">
            <li>Weekly practice plans</li>
            <li>Habit maps and short micro-lessons</li>
            <li>Peer check-ins and templates</li>
          </ul>
        </div>
        <div style="margin-top:12px">
          <a class="cta" href="book.html">Reserve a spot</a>
        </div>
      </aside>
    </section>

    <section class="wrap card reveal-hidden" style="margin-top:24px">
      <h3>Payment & group details</h3>
      <p class="small">All cohorts run with caps to keep feedback focused. We collect a deposit to hold your place and offer a short onboarding call before the cohort begins.</p>
      <div style="display:flex;gap:10px;margin-top:10px">
        <a class="btn-primary" href="book.html">Book onboarding call</a>
        <button class="btn-ghost" id="pricing-try">Try a short exercise</button>
      </div>
    </section>

    <section class="wrap reveal-hidden" style="margin-top:22px">
      <div class="card">
        <h3>Micro-habits we'll build</h3>
        <p class="small">A sample of the daily moves we anchor to: morning intention (3 items), 5-minute check-in at lunch, and a 7-minute evening wind-down with a short review.</p>
      </div>
    </section>

  </main>

  <footer>
    <div class="wrap">
      <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px">
        <div>{{BUSINESS_NAME}} — {{TAGLINE}}</div>
        <div class="small">Questions? <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
      </div>
    </div>
  </footer>

  <!-- Guided exercise modal -->
  <div id="overlay" class="overlay" aria-hidden="true">
    <div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">
      <h2 id="modal-title">Try a short practice</h2>
      <div class="steps" id="modal-steps">
        <div class="step" data-type="breathing">Breathing</div>
        <div class="step" data-type="journaling">Journaling</div>
        <div class="step" data-type="intention">Intention</div>
      </div>
      <div class="body" id="modal-body">
        <p class="small">Select one of the mini-practices above to try a guided version right now.</p>
      </div>
      <div class="controls">
        <button class="btn-ghost" id="close-modal">Close</button>
        <button class="btn-primary" id="start">Start</button>
      </div>
    </div>
  </div>

  <script>
    // Scroll reveal with prefers-reduced-motion support
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const items = document.querySelectorAll('.reveal-hidden');
      if(prefersReduced){ // reveal immediately
        items.forEach(i=>{ i.style.opacity=1; i.style.transform='none'; });
        return;
      }
      const obs = new IntersectionObserver((entries, o)=>{
        entries.forEach(e=>{
          if(e.isIntersecting){ e.target.classList.remove('reveal-hidden'); o.unobserve(e.target); }
        });
      },{threshold:0.08});
      items.forEach(i=>obs.observe(i));
    })();

    // Modal logic for guided exercise
    (function(){
      const overlay = document.getElementById('overlay');
      const tryBtns = [document.getElementById('try-btn'), document.getElementById('pricing-try')];
      const steps = document.getElementById('modal-steps');
      const body = document.getElementById('modal-body');
      const startBtn = document.getElementById('start');
      const closeBtn = document.getElementById('close-modal');
      let selected = 'breathing';
      function open(){ overlay.classList.add('open'); overlay.setAttribute('aria-hidden','false'); document.body.style.overflow='hidden'; }
      function close(){ overlay.classList.remove('open'); overlay.setAttribute('aria-hidden','true'); document.body.style.overflow=''; resetBody(); }
      function resetBody(){ body.innerHTML = '<p class="small">Select one of the mini-practices above to try a guided version right now.</p>'; startBtn.textContent='Start'; selected='breathing'; highlightSelection(); }
      function highlightSelection(){ Array.from(steps.children).forEach(el=>{ el.style.background = el.dataset.type===selected ? 'linear-gradient(90deg,#EDEBFF,#F6F5FF)' : ''; }); }

      tryBtns.forEach(b=> b && b.addEventListener('click', open));
      closeBtn.addEventListener('click', close);
      overlay.addEventListener('click', (e)=>{ if(e.target===overlay) close(); });

      steps.addEventListener('click', (e)=>{
        const el = e.target.closest('.step'); if(!el) return; selected = el.dataset.type; highlightSelection(); renderPreview();
      });

      startBtn.addEventListener('click', ()=>{
        if(selected==='breathing') runBreathing(60); // 60s session
        else if(selected==='journaling') runJournaling();
        else runIntention();
      });

      function renderPreview(){
        if(selected==='breathing'){
          body.innerHTML = '<p class="small">A one-minute paced breath: inhale for 4, hold 2, exhale 6. Follow the on-screen prompts and a small counter.</p>';
          startBtn.textContent='Begin breathing';
        }else if(selected==='journaling'){
          body.innerHTML = '<p class="small">A 3-step journaling prompt: notice • name • next. You get 3 minutes. Type into the quick box and finish with a snapshot.</p><textarea id="mini-journal" rows="6" style="width:100%;margin-top:8px;border-radius:8px;padding:8px;border:1px solid rgba(15,23,42,0.06)"></textarea>';
          startBtn.textContent='Begin journaling';
        }else{
          body.innerHTML = '<p class="small">Set a simple intention in one sentence. We guide you with clarifying prompts and a tiny timer to commit.</p><input id="intent-input" placeholder="Today I will..." style="width:100%;padding:8px;border-radius:8px;border:1px solid rgba(15,23,42,0.06);margin-top:8px">';
          startBtn.textContent='Set intention';
        }
      }

      function runBreathing(seconds){
        let remaining = seconds; startBtn.disabled=true; body.innerHTML = '<div style="font-size:28px;font-weight:700;text-align:center" id="breath-counter">'+remaining+'</div><p class="small" id="breath-prompt" style="text-align:center;margin-top:8px">Get ready...</p>';
        const counter = document.getElementById('breath-counter');
        const prompt = document.getElementById('breath-prompt');
        // cycle phases: inhale 4, hold 2, exhale 6 => 12s per cycle
        const phases = [{name:'Inhale',dur:4},{name:'Hold',dur:2},{name:'Exhale',dur:6}];
        let phaseIdx = 0; let phaseTime = phases[0].dur; let tick = 0;
        const iv = setInterval(()=>{
          remaining--; tick++;
          counter.textContent = remaining;
          prompt.textContent = phases[phaseIdx].name + ' — ' + (phaseTime - (tick % phaseTime)) + 's';
          if((tick % phaseTime)===0){ phaseIdx = (phaseIdx+1)%phases.length; phaseTime = phases[phaseIdx].dur; }
          if(remaining<=0){ clearInterval(iv); prompt.textContent='Well done — take a steady breath.'; startBtn.disabled=false; }
        },1000);
      }

      function runJournaling(){
        const ta = document.getElementById('mini-journal');
        if(!ta) return; startBtn.disabled=true; let t = 180; const timer = document.createElement('div'); timer.style.marginTop='8px'; timer.style.fontWeight='700'; body.appendChild(timer);
        timer.textContent = 'Time left: 3:00';
        const iv = setInterval(()=>{
          t--; const m=Math.floor(t/60); const s=('0'+(t%60)).slice(-2); timer.textContent = 'Time left: '+m+':'+s;
          if(t<=0){ clearInterval(iv); startBtn.disabled=false; timer.textContent='Time is up — nice work.'; }
        },1000);
      }

      function runIntention(){
        const inp = document.getElementById('intent-input');
        const text = inp && inp.value.trim();
        if(!text){ alert('Type a short intention first.'); return; }
        body.innerHTML = '<p class="small">You wrote:</p><div style="background:#f8fafc;padding:12px;border-radius:8px;margin-top:8px">'+escapeHtml(text)+'</div><p style="margin-top:8px;" class="small">Repeat it silently three times. Tap close when you feel steady.</p>';
      }

      function escapeHtml(s){ return s.replace(/[&<>\"']/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":"&#39;"}[c]; }); }

      // initial states
      highlightSelection(); renderPreview();
    })();
  </script>
</body>
</html>"} 
