<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Stories — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Real progress stories from cohort participants. Short, habit-focused case notes." />
  <style>
    :root{--bg:#fff6f9;--card:#fff;--accent:#ff6b8a;--muted:#475569}
    body{font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;margin:0;background:var(--bg);color:#0b1220}
    .wrap{max-width:1100px;margin:0 auto;padding:24px}
    header{padding:18px 0}
    nav{display:flex;justify-content:space-between;align-items:center}
    .nav a{color:var(--muted);text-decoration:none;margin-left:14px}
    .hero{padding:22px;background:linear-gradient(180deg,rgba(255,107,138,0.06),transparent);border-radius:12px}
    .hero h1{margin:0;font-size:24px}
    .hero p{margin:8px 0 0;color:var(--muted)}
    .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:18px}
    .card{background:var(--card);border-radius:12px;padding:16px;box-shadow:0 6px 20px rgba(11,18,32,0.06)}
    .quote{font-size:14px;color:#0b1220}
    .author{margin-top:12px;font-size:13px;color:var(--muted)}
    .cta{display:inline-block;background:var(--accent);color:#fff;padding:8px 12px;border-radius:10px;text-decoration:none}
    .reveal-hidden{opacity:0;transform:translateY(14px);transition:opacity .45s ease,transform .6s cubic-bezier(.2,.9,.3,1)}
    @media (prefers-reduced-motion: reduce){.reveal-hidden{opacity:1;transform:none;transition:none}}
    @media (max-width:900px){.grid{grid-template-columns:1fr}}
    footer{margin-top:30px;padding:24px;color:var(--muted)}
