  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <nav>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div>
          <a href="index.html">Home</a>
          <a href="programs.html">Journeys</a>
          <a href="pricing.html">Plans</a>
          <a href="book.html">Reserve</a>
        </div>
      </nav>
    </header>

    <section class="hero reveal-hidden">
      <h1>Progress notes from people who practiced with care</h1>
      <p>Short, focused stories about what shifted when habits got a clear place in the day.</p>
    </section>

    <main>
      <section class="grid" style="margin-top:16px">
        <article class="card reveal-hidden">
          <div class="quote">"I used to think I needed big mornings. After the cohort I built a 5-minute anchor that made afternoons steadier — more consistent energy and less overwhelm."</div>
          <div class="author">— Sam, Bridge Cohort</div>
        </article>

        <article class="card reveal-hidden">
          <div class="quote">"The weekly review tool changed my week. I can spot drift earlier and pull a small correction before stress builds."</div>
          <div class="author">— Priya, Anchor Cohort</div>
        </article>

        <article class="card reveal-hidden">
          <div class="quote">"Short journaling prompts helped me find one reliable habit: a two-minute note each evening. It feels tiny, but it shaped my next day."</div>
          <div class="author">— Marco, Launch Cohort</div>
        </article>

        <article class="card reveal-hidden">
          <div class="quote">"Community check-ins were practical and gentle. Not motivational pep-talks — actual accountability that fit my life."</div>
          <div class="author">— Lila, Micro Cohort</div>
        </article>

        <article class="card reveal-hidden">
          <div class="quote">"I didn't need more tools. I needed one repeatable practice I could do even on busy days. This gave me that."</div>
          <div class="author">— Jonah, Bridge Cohort</div>
        </article>

        <article class="card reveal-hidden">
          <div class="quote">"The coach's frameworks helped me map how small moves accumulate. It's easier to keep a practice when you can see it build."</div>
          <div class="author">— Andrea, Anchor Cohort</div>
        </article>

      </section>

      <section style="margin-top:18px">
        <div class="card reveal-hidden">
          <h3>Want to hear more?</h3>
          <p class="small">We keep a short digest of cohort notes and snapshots. Sign up for the occasional update, or book a brief chat to see which cohort fits.</p>
          <div style="margin-top:10px;display:flex;gap:8px;align-items:center">
            <a class="cta" href="book.html">Book a short consult</a>
            <button class="try-btn" id="try-btn">Try it now</button>
          </div>
        </div>
      </section>

    </main>

    <footer>
      <div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:10px">
        <div>{{BUSINESS_NAME}} • {{CITY}}, {{STATE}}</div>
        <div class="small">Contact: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
      </div>
    </footer>
  </div>

  <!-- Modal copied for this page -->
  <div id="overlay" class="overlay" aria-hidden="true" style="position:fixed;inset:0;display:none;align-items:center;justify-content:center;padding:20px;background:rgba(2,6,23,0.48);z-index:60">
    <div class="modal" style="background:#fff;border-radius:12px;padding:18px;max-width:640px;width:100%;box-shadow:0 10px 40px rgba(0,0,0,0.16)" role="dialog" aria-modal="true">
      <h2 style="margin:0 0 8px">Try a short practice</h2>
      <div style="display:flex;gap:8px;margin-bottom:10px">
        <div class="step" data-type="breathing" style="flex:1;padding:10px;background:rgba(255,107,138,0.08);border-radius:8px;text-align:center">Breathing</div>
        <div class="step" data-type="journaling" style="flex:1;padding:10px;background:rgba(255,107,138,0.04);border-radius:8px;text-align:center">Journaling</div>
        <div class="step" data-type="intention" style="flex:1;padding:10px;background:rgba(255,107,138,0.02);border-radius:8px;text-align:center">Intention</div>
      </div>
      <div id="modal-body"><p class="small">Select one to preview and start.</p></div>
      <div style="display:flex;justify-content:flex-end;margin-top:12px"><button id="close-modal" class="btn-ghost" style="margin-right:8px">Close</button><button id="start" class="btn-primary" style="background:#ff6b8a;color:#fff;padding:8px 12px;border-radius:8px;border:none">Start</button></div>
    </div>
  </div>

  <script>
    // Reveal logic
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const items = document.querySelectorAll('.reveal-hidden');
      if(prefersReduced){ items.forEach(i=>{ i.style.opacity=1; i.style.transform='none'; }); return; }
      const obs = new IntersectionObserver((entries, o)=>{ entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.remove('reveal-hidden'); o.unobserve(e.target); } }); },{threshold:0.08});
      items.forEach(i=>obs.observe(i));
    })();

    // Simple modal reused from pricing with limited features
    (function(){
      const overlay = document.getElementById('overlay');
      const tryBtn = document.getElementById('try-btn');
      const close = document.getElementById('close-modal');
      const start = document.getElementById('start');
      let selected = 'breathing';
      function open(){ overlay.style.display='flex'; overlay.setAttribute('aria-hidden','false'); document.body.style.overflow='hidden'; }
      function closeModal(){ overlay.style.display='none'; overlay.setAttribute('aria-hidden','true'); document.body.style.overflow=''; }
      if(tryBtn) tryBtn.addEventListener('click', open);
      close.addEventListener('click', closeModal);
      overlay.addEventListener('click', (e)=>{ if(e.target===overlay) closeModal(); });
      const steps = document.querySelectorAll('.step'); steps.forEach(s=>s.addEventListener('click', ()=>{ selected=s.dataset.type; render(); }));
      function render(){ const body = document.getElementById('modal-body'); if(selected==='breathing') body.innerHTML='<p class="small">One-minute grounding breath: inhale 4, hold 2, exhale 6. Hit start to follow and see a live count.</p>'; else if(selected==='journaling') body.innerHTML='<p class="small">Three quick prompts: notice, name, next. You get a short textarea to capture a note.</p><textarea style="width:100%;margin-top:8px;border-radius:8px;padding:8px" rows="5"></textarea>'; else body.innerHTML='<p class="small">Write a crisp intention and repeat it mentally three times.</p><input style="width:100%;padding:8px;border-radius:8px;margin-top:8px" placeholder="Today I will...">'; }
      start.addEventListener('click', ()=>{ alert('This page provides a quick guided preview — open the Plans page for the interactive variant.'); });
      render();
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Reserve a quick onboarding call or a cohort spot. Simple intake to match you to the right group." />
  <style>
    :root{--bg:#f7fff1;--card:#fff;--accent:#0ea5a4;--muted:#475569}
    body{font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;background:var(--bg);margin:0;color:#092126}
    .wrap{max-width:920px;margin:0 auto;padding:24px}
    header{display:flex;justify-content:space-between;align-items:center;padding:12px 0}
    nav a{margin-left:12px;color:var(--muted);text-decoration:none}
    main{margin-top:18px}
    .card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 10px 30px rgba(2,6,23,0.06)}
    form{display:grid;grid-template-columns:1fr 260px;gap:16px;margin-top:12px}
    .field{margin-bottom:10px}
    input,textarea,select{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(2,6,23,0.06)}
    .btn-primary{background:var(--accent);color:#fff;padding:10px 12px;border-radius:8px;border:none}
    .muted{color:var(--muted);font-size:13px}
    .reveal-hidden{opacity:0;transform:translateY(16px);transition:opacity .48s ease,transform .6s cubic-bezier(.2,.9,.3,1)}
    @media (prefers-reduced-motion: reduce){.reveal-hidden{opacity:1;transform:none;transition:none}}
    @media (max-width:860px){form{grid-template-columns:1fr}}
    footer{margin-top:24px;padding:24px;color:var(--muted)}
    .try-btn{background:transparent;border:1px solid rgba(2,6,23,0.06);padding:8px 10px;border-radius:8px}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div style="font-weight:700">{{BUSINESS_NAME}}</div>
      <nav>
        <a href="index.html">Home</a>
        <a href="services.html">Sessions</a>
        <a href="pricing.html">Plans</a>
        <a href="contact.html">Contact</a>
      </nav>
    </header>

    <main>
      <section class="card reveal-hidden">
        <h1>Reserve a spot or an onboarding call</h1>
        <p class="muted">Pick a short onboarding call to scope your goals, or reserve a cohort seat. We'll match you to a cohort rhythm that fits your week.</p>
        <div style="margin-top:12px;display:flex;gap:8px;align-items:center">
          <a class="btn-primary" href="#booking-form">Reserve</a>
          <button class="try-btn" id="try-btn">Try it now</button>
        </div>
      </section>

      <section id="booking-form" class="card reveal-hidden" style="margin-top:16px">
        <h3>Quick intake</h3>
        <form id="book-form">
          <div>
            <div class="field"><label class="muted">Full name</label><input name="name" required placeholder="Your name"></div>
            <div class="field"><label class="muted">Email</label><input name="email" type="email" required placeholder="you@domain.com"></div>
            <div class="field"><label class="muted">Phone</label><input name="phone" placeholder="Optional"></div>
            <div class="field"><label class="muted">What matters most right now?</label><textarea name="notes" rows="4" placeholder="A brief note about the habit or rhythm you'd like to build"></textarea></div>
            <div class="field"><label class="muted">Preferred offering</label>
              <select name="offering">
                <option>Launch Cohort — 3 weeks</option>
                <option>Bridge Cohort — 6 weeks</option>
                <option>Anchor Cohort — 12 weeks</option>
                <option>Onboarding Call (30 min)</option>
              </select>
            </div>
            <div style="margin-top:8px"><button class="btn-primary" type="submit">Request reservation</button></div>
          </div>

          <aside>
            <div class="muted">Booking details</div>
            <div style="margin-top:10px" class="muted">After you submit, you'll get an email to pick times. Deposits hold cohort seats; calls are complimentary with cohorts.</div>
            <div style="margin-top:10px" class="muted"><strong>Need a different time?</strong> Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
          </aside>
        </form>
      </section>

    </main>

    <footer>
      <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px">
        <div class="muted">© {{BUSINESS_NAME}} • {{CITY}}, {{STATE}}</div>
        <div class="muted">Questions? <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      </div>
    </footer>
  </div>

  <!-- Modal (same interactive modal included) -->
  <div id="overlay" style="position:fixed;inset:0;display:none;align-items:center;justify-content:center;padding:20px;background:rgba(2,6,23,0.48);z-index:60">
    <div style="background:#fff;border-radius:12px;padding:18px;max-width:680px;width:100%">
      <h2 style="margin:0 0 8px">Try a short practice</h2>
      <div style="display:flex;gap:8px;margin-bottom:10px">
        <div class="step" data-type="breathing" style="flex:1;padding:10px;border-radius:8px;background:rgba(14,165,164,0.08);text-align:center">Breathing</div>
        <div class="step" data-type="journaling" style="flex:1;padding:10px;border-radius:8px;background:rgba(14,165,164,0.04);text-align:center">Journaling</div>
        <div class="step" data-type="intention" style="flex:1;padding:10px;border-radius:8px;background:rgba(14,165,164,0.02);text-align:center">Intention</div>
      </div>
      <div id="modal-body"><p class="muted">Pick a mini-practice to preview and start.</p></div>
      <div style="display:flex;justify-content:flex-end;margin-top:12px"><button id="close-modal" style="margin-right:8px;padding:8px;border-radius:8px;border:1px solid rgba(2,6,23,0.06)">Close</button><button id="start" style="background:var(--accent);color:#fff;padding:8px;border-radius:8px;border:none">Start</button></div>
    </div>
  </div>

  <script>
    // Reveal logic
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const items = document.querySelectorAll('.reveal-hidden');
      if(prefersReduced){ items.forEach(i=>{ i.style.opacity=1; i.style.transform='none'; }); return; }
      const obs = new IntersectionObserver((entries,o)=>{ entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.remove('reveal-hidden'); o.unobserve(e.target); } }); },{threshold:0.08});
      items.forEach(i=>obs.observe(i));
    })();

    // Simple form handler (no backend)
    document.getElementById('book-form').addEventListener('submit', function(e){
      e.preventDefault();
      const data = new FormData(e.target); const name = data.get('name');
      alert('Thanks, ' + (name||'there') + '! We received your request and will follow up via email to set a time.');
      e.target.reset();
      window.scrollTo({top:0,behavior:'smooth'});
    });

    // Modal same guided exercise
    (function(){
      const overlay = document.getElementById('overlay');
      const tryBtn = document.getElementById('try-btn');
      const close = document.getElementById('close-modal');
      const start = document.getElementById('start');
      let selected = 'breathing';

      function open(){ overlay.style.display='flex'; document.body.style.overflow='hidden'; }
      function closeModal(){ overlay.style.display='none'; document.body.style.overflow=''; }
      if(tryBtn) tryBtn.addEventListener('click', open);
      close.addEventListener('click', closeModal);
      overlay.addEventListener('click', (e)=>{ if(e.target===overlay) closeModal(); });
      const steps = document.querySelectorAll('.step'); steps.forEach(s=>s.addEventListener('click', ()=>{ selected=s.dataset.type; render(); }));
      function render(){ const b = document.getElementById('modal-body'); if(selected==='breathing') b.innerHTML='<p class="muted">Minute breath cycle: inhale 4, hold 2, exhale 6. Start to follow the counter.</p>'; else if(selected==='journaling') b.innerHTML='<p class="muted">Three short prompts and a textarea to capture a tiny note.</p><textarea style="width:100%;margin-top:8px;border-radius:8px;padding:8px" rows="5"></textarea>'; else b.innerHTML='<p class="muted">Write a concise intention and repeat it silently three times.</p><input style="width:100%;padding:8px;border-radius:8px;margin-top:8px" placeholder="Today I will...">'; }
      start.addEventListener('click', ()=>{ alert('Interactive practices are available in the Plans page — open it to try the timed experience.'); });
      render();
    })();
  </script>
</body>
</html>"} 
